    COUNT(dp1.Object.yLnL_PS) AS count_yLnL_PS,
    MIN(dp1.Object.yLnL_PS) AS min_yLnL_PS,
    MAX(dp1.Object.yLnL_PS) AS max_yLnL_PS,
    COUNT(dp1.Object.yLnL_SG) AS count_yLnL_SG,
    MIN(dp1.Object.yLnL_SG) AS min_yLnL_SG,
    MAX(dp1.Object.yLnL_SG) AS max_yLnL_SG,
    COUNT(dp1.Object.yFlux_PS) AS count_yFlux_PS,
    MIN(dp1.Object.yFlux_PS) AS min_yFlux_PS,
    MAX(dp1.Object.yFlux_PS) AS max_yFlux_PS,
    COUNT(dp1.Object.yFlux_PS_Sigma) AS count_yFlux_PS_Sigma,
    MIN(dp1.Object.yFlux_PS_Sigma) AS min_yFlux_PS_Sigma,
    MAX(dp1.Object.yFlux_PS_Sigma) AS max_yFlux_PS_Sigma,
    COUNT(dp1.Object.yFlux_ESG) AS count_yFlux_ESG,
    MIN(dp1.Object.yFlux_ESG) AS min_yFlux_ESG,
    MAX(dp1.Object.yFlux_ESG) AS max_yFlux_ESG,
    COUNT(dp1.Object.yFlux_ESG_Sigma) AS count_yFlux_ESG_Sigma,
    MIN(dp1.Object.yFlux_ESG_Sigma) AS min_yFlux_ESG_Sigma,
    MAX(dp1.Object.yFlux_ESG_Sigma) AS max_yFlux_ESG_Sigma,
    COUNT(dp1.Object.yFlux_Gaussian) AS count_yFlux_Gaussian,
    MIN(dp1.Object.yFlux_Gaussian) AS min_yFlux_Gaussian,
    MAX(dp1.Object.yFlux_Gaussian) AS max_yFlux_Gaussian,
    COUNT(dp1.Object.yFlux_Gaussian_Sigma) AS count_yFlux_Gaussian_Sigma,
    MIN(dp1.Object.yFlux_Gaussian_Sigma) AS min_yFlux_Gaussian_Sigma,
    MAX(dp1.Object.yFlux_Gaussian_Sigma) AS max_yFlux_Gaussian_Sigma,
    COUNT(dp1.Object.yTimescale) AS count_yTimescale,
    MIN(dp1.Object.yTimescale) AS min_yTimescale,
    MAX(dp1.Object.yTimescale) AS max_yTimescale,
    COUNT(dp1.Object.yEarliestObsTime) AS count_yEarliestObsTime,
    MIN(dp1.Object.yEarliestObsTime) AS min_yEarliestObsTime,
    MAX(dp1.Object.yEarliestObsTime) AS max_yEarliestObsTime,
    COUNT(dp1.Object.yLatestObsTime) AS count_yLatestObsTime,
    MIN(dp1.Object.yLatestObsTime) AS min_yLatestObsTime,
    MAX(dp1.Object.yLatestObsTime) AS max_yLatestObsTime,
    COUNT(dp1.Object.ySersicN_SG) AS count_ySersicN_SG,
    MIN(dp1.Object.ySersicN_SG) AS min_ySersicN_SG,
    MAX(dp1.Object.ySersicN_SG) AS max_ySersicN_SG,
    COUNT(dp1.Object.ySersicN_SG_Sigma) AS count_ySersicN_SG_Sigma,
    MIN(dp1.Object.ySersicN_SG_Sigma) AS min_ySersicN_SG_Sigma,
    MAX(dp1.Object.ySersicN_SG_Sigma) AS max_ySersicN_SG_Sigma,
    COUNT(dp1.Object.yE1_SG) AS count_yE1_SG,
    MIN(dp1.Object.yE1_SG) AS min_yE1_SG,
    MAX(dp1.Object.yE1_SG) AS max_yE1_SG,
    COUNT(dp1.Object.yE1_SG_Sigma) AS count_yE1_SG_Sigma,
    MIN(dp1.Object.yE1_SG_Sigma) AS min_yE1_SG_Sigma,
    MAX(dp1.Object.yE1_SG_Sigma) AS max_yE1_SG_Sigma,
    COUNT(dp1.Object.yE2_SG) AS count_yE2_SG,
    MIN(dp1.Object.yE2_SG) AS min_yE2_SG,
    MAX(dp1.Object.yE2_SG) AS max_yE2_SG,
    COUNT(dp1.Object.yE2_SG_Sigma) AS count_yE2_SG_Sigma,
    MIN(dp1.Object.yE2_SG_Sigma) AS min_yE2_SG_Sigma,
    MAX(dp1.Object.yE2_SG_Sigma) AS max_yE2_SG_Sigma,
    COUNT(dp1.Object.yRadius_SG) AS count_yRadius_SG,
    MIN(dp1.Object.yRadius_SG) AS min_yRadius_SG,
    MAX(dp1.Object.yRadius_SG) AS max_yRadius_SG,
    COUNT(dp1.Object.yRadius_SG_Sigma) AS count_yRadius_SG_Sigma,
    MIN(dp1.Object.yRadius_SG_Sigma) AS min_yRadius_SG_Sigma,
    MAX(dp1.Object.yRadius_SG_Sigma) AS max_yRadius_SG_Sigma,
    COUNT(dp1.Object.yFlags) AS count_yFlags,
    MIN(dp1.Object.yFlags) AS min_yFlags,
    MAX(dp1.Object.yFlags) AS max_yFlags,
    COUNT(dp1.Object.varBinaryField) AS count_varBinaryField,
    MIN(dp1.Object.varBinaryField) AS min_varBinaryField,
    MAX(dp1.Object.varBinaryField) AS max_varBinaryField,
    COUNT(dp1.Object.chunkId) AS count_chunkId,
    MIN(dp1.Object.chunkId) AS min_chunkId,
    MAX(dp1.Object.chunkId) AS max_chunkId,
    COUNT(dp1.Object.subChunkId) AS count_subChunkId,
    MIN(dp1.Object.subChunkId) AS min_subChunkId,
    MAX(dp1.Object.subChunkId) AS max_subChunkId
FROM dp1.Object
WHERE objectId > 0
  AND flags >= 0
  AND ra_PS BETWEEN 0 AND 360
  AND decl_PS BETWEEN -90 AND 90
GROUP BY dp1.Object.canonicalFilterId, dp1.Object.extendedness
ORDER BY dp1.Object.canonicalFilterId, dp1.Object.extendedness
